@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile</h2>

    @if (isLoading)
    {
        <p>Loading profile...</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@model.AvatarUrl" alt="Avatar" class="avatar-image" />
            <span class="avatar-url">@model.AvatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="model.DisplayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="model.Email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="model.Bio" rows="4"></textarea>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (!string.IsNullOrEmpty(message))
        {
            <div class="toast @messageType">@message</div>
        }
    }
</div>

@code {
    private ProfileModel model = new();
    private UserProfile? savedProfile;
    private bool isLoading = true;
    private string message = "";
    private string messageType = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        MapToModel(savedProfile);
        isLoading = false;
    }

    private void MapToModel(UserProfile profile)
    {
        model = new ProfileModel
        {
            DisplayName = profile.DisplayName,
            Email = profile.Email,
            AvatarUrl = profile.AvatarUrl,
            Bio = profile.Bio
        };
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(model.DisplayName, model.Email, model.AvatarUrl, model.Bio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        message = "Profile saved successfully!";
        messageType = "toast-success";
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            MapToModel(savedProfile);
        }
        message = "Changes discarded.";
        messageType = "toast-info";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        message = "";
        await InvokeAsync(StateHasChanged);
    }

    private class ProfileModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}

@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notifications</h2>

    @if (isLoading)
    {
        <p>Loading notification preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-row">
                <input type="checkbox" @bind="emailNotifications" />
                <span>Email Notifications</span>
            </label>

            <label class="toggle-row">
                <input type="checkbox" @bind="pushNotifications" />
                <span>Push Notifications</span>
            </label>

            <label class="toggle-row">
                <input type="checkbox" @bind="weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                <label class="toggle-row">
                    <input type="checkbox"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SavePreferences">Save Preferences</button>
        </div>

        @if (!string.IsNullOrEmpty(message))
        {
            <div class="toast toast-success">@message</div>
        }
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];
    private bool isLoading = true;
    private string message = "";

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        message = "Preferences saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        message = "";
        await InvokeAsync(StateHasChanged);
    }
}

@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security</h2>

    @if (isLoading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelOpen ? "▾" : "▸")</span>
            </button>

            @if (passwordPanelOpen)
            {
                <div class="panel-content">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="toast toast-error">@passwordError</div>
                    }

                    <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="toggle-row">
                <span class="status-indicator @(twoFactorEnabled ? "status-active" : "status-inactive")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <label class="toggle-row">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span>Enable 2FA</span>
                </label>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != sessions.FirstOrDefault())
                                {
                                    <button class="btn-danger btn-small"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in @sessionToRevoke.Location?</p>
                    <div class="button-group">
                        <button class="btn-danger" @onclick="RevokeSession">Revoke</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }

        @if (!string.IsNullOrEmpty(message))
        {
            <div class="toast toast-success">@message</div>
        }
    }
</div>

@code {
    private bool isLoading = true;
    private bool passwordPanelOpen;
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = new();
    private ActiveSession? sessionToRevoke;

    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private string message = "";

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = settings.Sessions.ToList();
        isLoading = false;
    }

    private async Task UpdatePassword()
    {
        passwordError = "";

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        passwordPanelOpen = false;
        message = "Password updated successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            sessions.Remove(sessionToRevoke);
            sessionToRevoke = null;
            message = "Session revoked.";
            _ = ClearMessageAfterDelay();
        }
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        message = "";
        await InvokeAsync(StateHasChanged);
    }
}

@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (isLoading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label><input type="radio" name="theme" value="Light" @onchange="() => theme = &quot;Light&quot;" checked="@(theme == "Light")" /> Light</label>
                <label><input type="radio" name="theme" value="Dark" @onchange="() => theme = &quot;Dark&quot;" checked="@(theme == "Dark")" /> Dark</label>
                <label><input type="radio" name="theme" value="System" @onchange="() => theme = &quot;System&quot;" checked="@(theme == "System")" /> System</label>
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label><input type="radio" name="fontSize" value="Small" @onchange="() => fontSize = &quot;Small&quot;" checked="@(fontSize == "Small")" /> Small</label>
                <label><input type="radio" name="fontSize" value="Medium" @onchange="() => fontSize = &quot;Medium&quot;" checked="@(fontSize == "Medium")" /> Medium</label>
                <label><input type="radio" name="fontSize" value="Large" @onchange="() => fontSize = &quot;Large&quot;" checked="@(fontSize == "Large")" /> Large</label>
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="language">
