+    justify-content: center;
+    z-index: 1000;
+}
+
+::deep .dialog {
+    background: white;
+    border-radius: 8px;
+    padding: 1.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
+}
+
+::deep .dialog h4 {
+    margin: 0 0 0.75rem;
+}
+
+::deep .dialog p {
+    margin: 0 0 1.25rem;
+    color: #495057;
+}
+
+/* Appearance Preview */
+::deep .preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    transition: all 0.3s ease;
+}
+
+::deep .preview-theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+::deep .preview-theme-dark {
+    background: #1a1a2e;
+    color: #e0e0e0;
+}
+
+::deep .preview-theme-system {
+    background: #f8f9fa;
+    color: #212529;
+}
+
+::deep .preview-font-small {
+    font-size: 0.8rem;
+}
+
+::deep .preview-font-medium {
+    font-size: 1rem;
+}
+
+::deep .preview-font-large {
+    font-size: 1.2rem;
+}
+
+::deep .preview-compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+::deep .preview-card {
+    margin-top: 1rem;
+    padding: 1rem;
+    border: 1px solid currentColor;
+    border-radius: 6px;
+    opacity: 0.8;
+}
+
+/* Channel List */
+::deep .channel-list {
+    max-height: 200px;
+    overflow-y: auto;
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+    padding: 0.5rem;
+}
+
+@keyframes fadeIn {
+    from { opacity: 0; transform: translateY(-4px); }
+    to { opacity: 1; transform: translateY(0); }
+}
+

